pageCss:
.pqc-tiers{border-collapse:collapse;width:100%;margin:0 0 14px;font-size:9.5pt}
.pqc-tiers th{text-align:left;background:#eaf0f9;border:1px solid #c3ceE0;padding:4px 7px;font-family:var(--font-caption)}
.pqc-tiers td{border:1px solid #d8dfeb;padding:4px 7px;vertical-align:top}
.pqc-tiers tr.mine td{background:#fffbe8}
.pqc-demo,.pqc-live{border:1px solid #99a8bd;background:#f3f6fa;box-shadow:inset 1px 1px 0 #fff;margin:0 0 14px}
.pqc-demo-head,.pqc-live-head{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;background:linear-gradient(180deg,#eaf0f9,#dbe4f1);border-bottom:1px solid #b6c2d4;padding:5px 9px;font-family:var(--font-caption);font-weight:bold;font-size:9.5pt;color:#20406e}
.pqc-toggle button{font:inherit;font-size:8.5pt;font-weight:normal;font-family:var(--font-ui);padding:2px 8px;cursor:pointer;background:linear-gradient(180deg,#fff,#e4e9f2);border:1px solid #8c9ab0;border-radius:3px;color:#243}
.pqc-toggle button.on{background:linear-gradient(180deg,#cddcf2,#aec4e6);border-color:#5a7398;box-shadow:inset 1px 1px 2px rgba(0,0,0,.18)}
.pqc-bars{list-style:none;margin:0;padding:10px 12px 4px}
.pqc-bars li{display:grid;grid-template-columns:8.5em 1fr auto;align-items:center;gap:8px;margin:0 0 7px;font-size:9pt}
.pqc-bars .n{font-family:var(--font-mono);color:#33455f;white-space:nowrap}
.pqc-bars .t{height:15px;background:linear-gradient(180deg,#7fb0e8,#3f7fd0);border:1px solid #2f5f9e;min-width:2px;transition:width .28s ease}
.pqc-bars li.now .t{background:linear-gradient(180deg,#8fd98f,#3ea23e);border-color:#2c7a2c}
.pqc-bars li.native .t{background:linear-gradient(180deg,#e6b45c,#c8880f);border-color:#9a6a08}
.pqc-native{border-top:1px solid #ccd6e4;padding:8px 12px;display:flex;align-items:center;gap:9px;flex-wrap:wrap}
.pqc-native-note{font-size:8.5pt;color:#5b6879;flex:1;min-width:14em}
.pqc-run{font:inherit;font-size:8.5pt;font-family:var(--font-ui);padding:3px 11px;cursor:pointer;background:linear-gradient(180deg,#fff,#e4e9f2);border:1px solid #8c9ab0;border-radius:3px}
.pqc-run:disabled{color:#8b96a6;cursor:default}
.pqc-bars .v{font-family:var(--font-mono);font-size:8.5pt;color:#4a5870;white-space:nowrap}
.pqc-read{margin:0;padding:2px 12px 10px;font-size:8.5pt;color:#5b6879}
.pqc-live-body{padding:8px 10px;font-family:var(--font-mono);font-size:8.5pt;color:#33455f;word-break:break-all;line-height:1.6}
.pqc-live-body b{font-family:var(--font-ui)}
.pqc-retired{border-left:3px solid oklch(41.92% 0.0962 250.51);background:oklch(96.5% 0.012 250.51);padding:8px 10px;margin:0 0 14px}
.pqc-retired p{margin:0}
.pqc-falsify{border-left:3px solid #c9a227;background:#fffbe8;padding:8px 10px;margin:14px 0 0}
@media(max-width:620px){.pqc-bars li{grid-template-columns:7em 1fr;row-gap:2px}.pqc-bars .v{grid-column:2}}

pageJs:
(function(){
  // Measured with @noble/post-quantum 0.6.1 on an M3 Max under Node 26.
  // sign is the median of 5 runs of 300 signatures over this site's real
  // signature base; ML-DSA is rejection-sampled, so it varies by design.
  var ROWS = [
    { n: "Ed25519",      bytes: 88,    sign: 0.05,    now: true },
    { n: "ML-DSA-44",    bytes: 3228,  sign: 8.58 },
    { n: "SLH-DSA-128s", bytes: 10476, sign: 2650 },
    { n: "SLH-DSA-128f", bytes: 22784, sign: 132.34 }
  ];
  var NOTE = {
    bytes: "Base64'd signature as it sits in the Signature header. Most servers cap total request headers near 8KB, which rules out both hash-based rows.",
    sign: "Single-threaded JavaScript, log scale. Ed25519 is roughly 170x faster than ML-DSA-44 and still leaves headroom on a background crawl."
  };
  var host = document.getElementById("pqc-demo");
  if (!host) return;
  var list = host.querySelector(".pqc-bars"), read = host.querySelector(".pqc-read");
  var metric = "bytes";

  function fmt(v) {
    if (metric === "bytes") return v.toLocaleString("en-US") + " B";
    // a native ML-DSA result can land well under 0.01ms, where two decimals
    // would round a real measurement down to "0.00".
    var s = v < 0.1 ? v.toPrecision(2) : v < 100 ? v.toFixed(1) : Math.round(v).toLocaleString("en-US");
    return s + " ms";
  }
  // bytes read honestly on a linear scale; sign times span microseconds to
  // seconds, where linear would collapse every fast row into nothing.
  function width(v, max) {
    if (metric === "bytes") return (v / max) * 100;
    // floor at 1us so a sub-microsecond result cannot produce a negative width
    var lo = Math.log10(Math.max(v, 0.001) * 1000);
    return Math.max(2, (lo / Math.log10(max * 1000)) * 100);
  }
  function render() {
    var max = ROWS.reduce(function (m, r) { return Math.max(m, r[metric]); }, 0);
    list.innerHTML = ROWS.map(function (r) {
      return '<li class="' + (r.now ? "now" : r.native ? "native" : "") + '"><span class="n">' + r.n +
        '</span><span class="t" style="width:' + width(r[metric], max).toFixed(1) +
        '%"></span><span class="v">' + fmt(r[metric]) + "</span></li>";
    }).join("");
    read.textContent = NOTE[metric];
  }
  [].forEach.call(host.querySelectorAll(".pqc-toggle button"), function (b) {
    b.addEventListener("click", function () {
      metric = b.getAttribute("data-metric");
      [].forEach.call(host.querySelectorAll(".pqc-toggle button"), function (o) {
        o.classList.toggle("on", o === b);
      });
      render();
    });
  });
  render();

  // Chrome puts ML-DSA in WebCrypto behind chrome://flags/#webcrypto-pqc. If the
  // reader has it on, let their hardware answer "how much of 8.58ms was the JIT?"
  // rather than asserting a speedup this page never measured.
  var nativeBox = host.querySelector(".pqc-native");
  var BASE = new TextEncoder().encode(
    '"@authority": example.com\n"signature-agent": "https://aadhar.sh/"\n' +
    '"@signature-params": ("@authority" "signature-agent");created=1785186311;' +
    'keyid="rn-mldsa-2026-07-27";alg="ml-dsa-44";tag="web-bot-auth"');

  function show(msg) { nativeBox.hidden = false; nativeBox.innerHTML = msg; }

  crypto.subtle.generateKey({ name: "ML-DSA-44" }, true, ["sign", "verify"]).then(function (key) {
    show('<button type="button" class="pqc-run">Run ML-DSA-44 natively, here</button>' +
         '<span class="pqc-native-note">Your browser has native ML-DSA. 200 signatures, on your hardware.</span>');
    nativeBox.querySelector(".pqc-run").addEventListener("click", function (e) {
      e.target.disabled = true;
      e.target.textContent = "signing\u2026";
      // yield first so the button repaints before the main thread is busy
      setTimeout(function () {
        var alg = { name: "ML-DSA-44" }, warm = [];
        for (var i = 0; i < 20; i++) warm.push(crypto.subtle.sign(alg, key.privateKey, BASE));
        Promise.all(warm).then(function () {
          var t0 = performance.now(), runs = [];
          for (var j = 0; j < 200; j++) runs.push(crypto.subtle.sign(alg, key.privateKey, BASE));
          return Promise.all(runs).then(function (sigs) {
            var ms = (performance.now() - t0) / 200;
            ROWS.push({
              n: "ML-DSA-44 (native)",
              bytes: Math.ceil(sigs[0].byteLength / 3) * 4,
              sign: ms, native: true,
            });
            metric = "sign";
            [].forEach.call(host.querySelectorAll(".pqc-toggle button"), function (o) {
              o.classList.toggle("on", o.getAttribute("data-metric") === "sign");
            });
            render();
            show('<span class="pqc-native-note"><b>' + (ms < 0.1 ? ms.toPrecision(2) : ms.toFixed(2)) +
                 "ms</b> per signature natively, versus 8.58ms in JavaScript: about <b>" +
                 Math.round(8.58 / ms) + "x</b>. Same " + sigs[0].byteLength.toLocaleString("en-US") +
                 " bytes on the wire, because that part is FIPS 204 and no implementation gets to improve it.</span>");
          });
        }).catch(function () { show('<span class="pqc-native-note">The native run failed partway.</span>'); });
      }, 30);
    });
  }).catch(function () {
    show('<span class="pqc-native-note">Your browser has no native ML-DSA. Chrome hides it behind ' +
         '<code>chrome://flags/#webcrypto-pqc</code>; turn it on and reload to benchmark the native ' +
         'implementation against the JavaScript number above.</span>');
  });

  // Read the site's own key directory so the page cannot drift from the key
  // the bot actually signs with.
  var live = document.querySelector("#pqc-live .pqc-live-body");
  if (!live) return;
  fetch("/.well-known/http-message-signatures-directory").then(function (r) {
    return r.json();
  }).then(function (dir) {
    var akp = (dir.keys || []).filter(function (k) { return k.kty === "AKP"; })[0];
    var ed = (dir.keys || []).filter(function (k) { return k.crv === "Ed25519"; })[0];
    if (!akp) {
      live.innerHTML = (ed ? "<b>" + ed.kid + "</b> &middot; kty " + ed.crv + " &middot; <b>32 bytes</b>, and the only key this bot signs with.<br>" : "") +
        "<span style='font-family:var(--font-ui)'>No AKP key: the ML-DSA label was retired on 2026-08-15. See below.</span>";
      return;
    }
    var raw = atob(akp.pub.replace(/-/g, "+").replace(/_/g, "/"));
    live.innerHTML =
      "<b>" + akp.kid + "</b> &middot; kty " + akp.kty + " &middot; alg " + akp.alg +
      " &middot; <b>" + raw.length.toLocaleString("en-US") + " bytes</b> of public key" +
      (ed ? "<br><b>" + ed.kid + "</b> &middot; kty " + ed.crv + " &middot; <b>32 bytes</b>, and the one your verifier should use" : "") +
      "<br>" + akp.pub.slice(0, 96) + "&hellip; <span style='font-family:var(--font-ui)'>(" +
      akp.pub.length.toLocaleString("en-US") + " base64url chars)</span>";
  }).catch(function () {
    live.textContent = "Could not read the key directory from here.";
  });
})();
